import { AgentRuntimeClient, RuntimeEnvelope } from '../index';

/**
 * e2bSandboxExecutor safely executes Python or Bash code generated by an agent
 * by routing it to an ephemeral e2b sandbox, but ONLY if the Agent Runtime Policy
 * allows the 'sandbox_execute' intent.
 */
export class E2BSecureSandbox {
  constructor(
    private e2bApiKey: string,
    private runtimeClient: AgentRuntimeClient,
    private policySetId: string,
    private envelope: RuntimeEnvelope
  ) {}

  async executeCode(language: 'python' | 'bash', code: string): Promise<string> {
    const action = {
      actionIntent: 'sandbox_execute',
      context: { language, code }
    };

    const decision = await this.runtimeClient.evaluateAction(this.policySetId, action, this.envelope);

    if (decision.outcome === 'DENY') {
      throw new Error(`Sandbox execution blocked by runtime policy.`);
    }

    if (decision.outcome === 'REQUIRE_APPROVAL') {
      throw new Error(`Sandbox execution paused for human approval.`);
    }

    // In a real implementation, we would import '@e2b/sdk' and create a sandbox
    // For this prototype, we simulate the network call to the e2b cluster
    console.log(`[E2B Sandbox] Spawning ephemeral microVM...`);
    console.log(`[E2B Sandbox] Executing ${language} code securely...`);
    
    // Simulating sandbox stdout
    return `Execution successful. stdout: Hello from Secure Sandbox!`;
  }
}
